/* Shared local navigation, no financial input transfer or storage migration. */
function centralNorteDestination(hash){
 const p=(hash||'').replace(/^#/,'').split('/'),kind=p[0],slug=p[1]||'';
 if(['mijn-plan','eigen-plan'].includes(kind))return '/ontwerp/klantreis-preview-09-11/?mijnplan=1';
 if(['voorbereiden','beginnen','voorbereiding-klaar','afspraak','afspraak-klaar'].includes(kind))return '/klantreis/?instap=plan';
 if(['adviseur-plan','bevestigd-plan'].includes(kind)||(kind==='samen'&&slug==='plan'))return '../kennis/?v=kennis-20261106-v2#plan-adviseur';
 if(kind==='ontdekken')return '../kennis/?v=kennis-20261106-v2#ontdekken';
 if(kind==='leren'){const lessons={spreiding:'spreiding',kosten:'kosten',fondsen:'fondsen-etf'};return '../kennis/?v=kennis-20261106-v2#'+(lessons[slug]?'a-'+lessons[slug]:'leren');}
 if(kind==='lezen'){const aliases={banken:'fortis',winnaar:'fortis',fonds:'fondsen-etf',fondsen:'fondsen-etf',ritme:'regelmatige-inleg',kind:'van-ooit-naar-plan',tijd:'risico-horizon',inflatie:'inflatie',kosten:'kosten',spreiding:'spreiding',rendement:'rendement',asml:'asml',buffer:'buffer',aandelen:'aandelen',obligaties:'obligaties',spaargeld:'spaarrekening',rente:'rente'};return '../kennis/?v=kennis-20261106-v2#'+(aliases[slug]?'a-'+aliases[slug]:'bibliotheek');}
 if(kind==='proberen')return '../kennis/?v=kennis-20261106-v2#verkennen-'+(slug==='kosten'?'kosten':'spreiding');
 if(kind==='simuleren')return '/klantreis/';
 if(/^(?:a-|k-|pad-|verkennen-|bibliotheek)/.test(kind)&&/^[a-z0-9-]+$/.test(kind))return '../kennis/?v=kennis-20261106-v2#'+kind;
 return null;
}
const root=document.querySelector('#main'),dialog=document.querySelector('#help-dialog');
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>';
const backArrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12H5m6-6-6 6 6 6"/></svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(label,href,cls='text-action')=>`<a class="${cls}" href="${href}">${label}${arrow}</a>`;
const back=(label,href)=>`<a class="back" href="${href}">${backArrow}${label}</a>`;
let artCounter=0;
function artwork(theme='green'){const id='koers-art-'+(++artCounter),dark=theme==='green';return `<svg class="koers-art" viewBox="0 0 700 620" aria-hidden="true"><defs><linearGradient id="${id}-face" x1=".15" x2=".85" y1=".15" y2=".9"><stop stop-color="${dark?'#cbd6c6':'#b7c8ba'}"/><stop offset=".5" stop-color="${dark?'#f1efdf':'#365c57'}"/><stop offset="1" stop-color="${dark?'#b3c5b6':'#1f3e38'}"/></linearGradient><linearGradient id="${id}-edge" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${dark?'#e8e9d8':'#84a498'}"/><stop offset="1" stop-color="${dark?'#7e9f8b':'#294b43'}"/></linearGradient></defs><g class="art-shape"><path d="M98 500 318 158Q349 109 401 138L645 273 425 615Z M210 475 350 260 530 335 390 550Z" fill-rule="evenodd" fill="${dark?'#1c3832':'#d6d8c9'}" opacity=".26"/><path d="M81 442 301 100Q331 55 377 81L620 216 400 558Z M192 416 331 199Q344 180 365 191L509 271 370 488Z" fill-rule="evenodd" fill="url(#${id}-edge)"/><path d="M81 417 301 75Q331 30 377 56L620 191 400 533Z M192 391 331 174Q344 155 365 166L509 246 370 463Z" fill="url(#${id}-face)" fill-rule="evenodd"/><path d="m192 391 139-217q13-19 34-8l144 80-16 25-141-79-144 224Z" fill="${dark?'#749580':'#183e36'}"/><path d="M81 417 400 533 400 558 81 442Z" fill="${dark?'#8ea88f':'#294d44'}"/><path d="m400 533 220-342v25L400 558Z" fill="${dark?'#d8ddc9':'#729788'}"/><path d="m81 417 220-342q30-45 76-19l243 135" fill="none" stroke="${dark?'#f6f3ec':'#ccdbcb'}" stroke-width="1.2" opacity=".8"/></g></svg>`;}

const topics={buffer:{name:'Uw financiële ruimte',category:'Overzicht & reserve',title:'Wat wilt u achter de hand houden?',lead:'Overzicht begint bij het verschil tussen geld dat al een bestemming heeft en ruimte die nog vrij is.',body:'Een onverwachte uitgave en een plan voor later vragen iets anders van uw geld. Door die twee uit elkaar te houden, worden uw keuzes duidelijker.',next:'Uw financiële situatie',stage:2},kind:{name:'Een kind helpen',category:'Familie & later',title:'Een goede start. Op hun eigen moment.',lead:'Een eerste sleutel, studies of ruimte om een eigen weg te kiezen. Wat wilt u voor een kind mogelijk maken?',body:'Begin bij de betekenis van die hulp. Wat wilt u zelf behouden, wanneer wilt u helpen en hoeveel ruimte wilt u daarvoor maken? Het antwoord hoeft nog niet vast te liggen.',next:'Uw doelen',stage:3},tijd:{name:'Meer tijd voor uzelf',category:'Werk & vrijheid',title:'Wat als later wat eerder begint?',lead:'Een dag minder werken of meer ruimte voor iets anders. Een financiële vraag begint vaak bij een wens voor uw leven.',body:'Breng in beeld wat u wilt veranderen en wanneer. Uw situatie, de ruimte die u heeft en andere plannen horen bij hetzelfde verhaal.',next:'Uw doelen',stage:3}};
let state={topic:null,goal:'',year:'',step:3,tab:'doelen',questions:{}};
try{Object.assign(state,JSON.parse(sessionStorage.getItem('norte-koers-demo')||'{}'));}catch{}
const persist=()=>{try{sessionStorage.setItem('norte-koers-demo',JSON.stringify(state));}catch{}};
if(state.demoConfirmed&&!state.confirmedDemoSnapshot&&state.requestDemo){state.confirmedDemoSnapshot=JSON.parse(JSON.stringify(state.requestDemo));persist();}
const topic=()=>topics[state.topic];
const context=()=>{const concept=state.preparationConcept,trial=state.preparationSimulation;if(concept)return `<p class="context-tag"><a class="trial-link" data-concept-trial="true" href="#proberen/spreiding">Uw verkenning: spreiding ${arrow}</a></p>`;if(!topic()&&!trial)return '';const label=`Verkenning: ${topic()?esc(topic().name):'maandelijks opzijzetten'}${trial?` · ${euros(trial.monthly)} per maand, ${trial.years} jaar`:''}`;return `<p class="context-tag">${trial?`<a class="trial-link" data-sim-trial="true" href="#simuleren${state.topic?'/'+state.topic:''}">${label}${arrow}</a>`:label}</p>`;};
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches||new URLSearchParams(location.search).get('motion')==='off';
document.documentElement.dataset.motion=reduced?'off':'on';
const steps=[['Klant','Wie hoort er bij uw plan?','De personen en uw situatie vormen het vertrekpunt.'],['Financiële situatie','Wat is uw vertrekpunt?','Uw inkomsten, uitgaven, bezit en reserve krijgen samen betekenis.'],['Doelen','Wat wilt u mogelijk maken?','Geef uw wensen een richting, een moment en een plaats in het geheel.'],['Strategie','Welke aanpak past bij u?','Bekijk risico, draagkracht en de aanpak van uw doelen in samenhang.']];
const process=()=>`<ol class="process-list">${steps.map((s,i)=>`<li><span class="n">0${i+1}</span><div><h2>${s[0]}</h2><p>${s[2]}</p></div></li>`).join('')}</ol>`;

const journalEntries={
winnaar:{type:'verhalen',kind:'Beleggingsverhaal',title:'De verleiding van één winnaar.',lead:'Een bedrijf kan een sterk verhaal hebben. Maar hoeveel van uw eigen verhaal wilt u eraan verbinden?',concept:'spreiding',source:'https://www.wikifin.be/nl/sparen-en-beleggen/checklist-beleggen',body:`<p>Stel: u volgt één bedrijf. U begrijpt wat het maakt, u ziet het overal en u gelooft in de toekomst ervan. Het voelt vertrouwd. In dit fictieve verhaal is dat het vertrekpunt.</p><h2>Een bedrijf is nog geen geheel.</h2><p>De vraag gaat verder dan dat bedrijf. Hoe zwaar weegt het naast uw andere beleggingen, uw reserve en de plannen die u voor later heeft?</p><blockquote>Een overtuigend verhaal kan nog altijd een grote afhankelijkheid zijn.</blockquote><h2>Maak het eens kleiner.</h2><p>In de verkenning naast dit verhaal kunt u het gewicht van één positie veranderen. Zo ziet u wat een tegenvaller in die positie met het voorbeeldgeheel doet.</p><p>Spreiding neemt niet elk risico weg. Het is een onderwerp om in samenhang met uw situatie te bespreken.</p>`},
fonds:{type:'leren',kind:'Producten & begrippen',title:'Eén fonds. Wat zit erin?',lead:'De verpakking vertelt niet alles. De beleggingen in een fonds bepalen mee waar u van afhankelijk bent.',concept:'spreiding',source:'https://www.wikifin.be/nl/sparen-en-beleggen/beleggingsproducten/beleggingsfonds/wat-zijn-de-risicos-van-een-beleggingsfonds',body:`<p>Een fonds kan verschillende beleggingen samenbrengen. Toch zegt het aantal namen alleen niet genoeg over de spreiding.</p><h2>Kijk onder de verpakking.</h2><p>Een fonds kan bijvoorbeeld sterk op één sector of regio gericht zijn. Dan blijft er een concentratie bestaan. De waarde van een fonds kan dalen.</p><h2>Begrijpen vóór kiezen.</h2><p>Welke beleggingen zitten erin? Welke risico’s en kosten horen erbij? Het KID en prospectus geven informatie over het specifieke fonds. Uw adviseur helpt die informatie bij uw eigen situatie te plaatsen.</p>`},
asml:{type:'bedrijven',kind:'Achter het bedrijf · ASML',title:'De wereld achter één chip.',lead:'Van een alledaags voorwerp naar de technologie die het mogelijk maakt. Een kijkje achter een onderneming.',concept:'spreiding',source:'https://www.asml.com/en/company/about-asml',body:`<figure class="company-figure"><img src="beelden/asml-lab.jpg" alt="Medewerkers in een ASML-laboratorium" width="1920" height="958"><figcaption>Beeld: ASML</figcaption></figure><h2>Patronen op een heel kleine schaal.</h2><p>ASML ontwerpt en maakt lithografiemachines voor de chipindustrie. Met licht brengen die machines patronen aan die de basis vormen voor schakelingen in chips.</p><h2>Het bedrijf en uw plan.</h2><p>Een onderneming begrijpen is iets anders dan bepalen welke plaats een belegging in uw plan krijgt. Ook een interessant bedrijf kan een grote afhankelijkheid worden als het te zwaar weegt.</p><p>Dit bedrijfsverhaal is geen koopadvies. De bijbehorende verkenning gaat over het gewicht van een willekeurige positie, niet over een voorspelling voor ASML.</p>`},
ritme:{type:'verhalen',kind:'Een principe in de praktijk',title:'Kleine stappen. Een lange adem.',lead:'Wat gebeurt er als u niet op één groot moment wacht, maar regelmatig iets opzijzet?',concept:'inleg',body:`<p>Een bedrag dat overzichtelijk voelt, kan met de jaren een groter geheel vormen. Begin bij wat u zelf inlegt, vóór u over een mogelijk rendement nadenkt.</p><h2>Wat u zelf toevoegt.</h2><p>De snelle simulatie telt de maandelijkse inleg over de gekozen jaren op. Ze veronderstelt geen rendement. Zo blijft duidelijk welk deel uit uw eigen bijdragen komt.</p><h2>En waarvoor?</h2><p>Een gewoonte krijgt betekenis door het doel erachter. Tijd, reserve en andere wensen bepalen mee welke ruimte u wilt maken.</p>`},
spreiding:{type:'leren',kind:'Een concept begrijpen',title:'Spreiden: waar bent u van afhankelijk?',lead:'Niet alleen het aantal beleggingen telt. Ook hun gewicht en onderlinge samenhang doen ertoe.',concept:'spreiding',source:'https://www.wikifin.be/nl/sparen-en-beleggen/checklist-beleggen',body:`<p>Spreiding betekent dat u uw beleggingen verdeelt. Daarmee voorkomt u dat u voor alles van dezelfde bron afhankelijk bent.</p><h2>Eén tegenvaller, welk gevolg?</h2><p>De verkenning laat één eenvoudig verband zien: het gewicht van een positie bepaalt mee hoeveel haar verandering in het geheel doorwerkt. De rest van de voorbeeldportefeuille blijft daarbij onveranderd.</p><p>Dat is geen complete risicobeoordeling. Beleggingen kunnen samen dalen en spreiding voorkomt niet elk verlies.</p>`}
};
Object.entries(journalEntries).forEach(([id,x])=>topics[id]={name:({spreiding:'Spreiding',winnaar:'Spreiding',fonds:'Fondsen begrijpen',asml:'Een bedrijf in het geheel',ritme:'Regelmatige inleg'}[id]||x.title),category:x.kind,title:x.title,lead:x.lead,body:'',stage:4});
function spreadArt(cls=''){return `<div class="spread-illustration ${cls}" aria-hidden="true">${Array.from({length:16},(_,i)=>`<span class="${i===5?'standout':''}"></span>`).join('')}</div>`;}
function fundArt(){return `<div class="fund-illustration" aria-hidden="true"><div>${Array.from({length:12},(_,i)=>`<span style="--i:${i}"></span>`).join('')}</div></div>`;}
function journalCard(id){const x=journalEntries[id];return `<a class="journal-card journal-${id}" href="#lezen/${id}">${id==='asml'?'<div class="journal-image"><img src="beelden/asml-campus.jpg" alt="" width="1920" height="1280" loading="lazy"></div>':id==='fonds'?fundArt():id==='ritme'?'<div class="habit-illustration" aria-hidden="true"><span>€200</span><div>'+Array(12).fill('<i></i>').join('')+'</div></div>':spreadArt()}<div class="journal-card-copy"><span class="small-label">${x.kind}</span><h2>${x.title}</h2>${arrow}</div></a>`;}
function discover(){const filter=location.hash.split('/')[1]||'alles',chosen=['leren','verhalen','bedrijven'].includes(filter)?filter:'alles',all=chosen==='alles';return `<div class="subpage-top">${back('Startpagina','#start')}</div><section class="journal-heading"><h1>Een nieuw perspectief.</h1><nav class="journal-filters" aria-label="Soort inhoud">${[['alles','Alles'],['leren','Begrijpen'],['verhalen','Verhalen'],['bedrijven','Bedrijven']].map(([id,label])=>`<button aria-pressed="${chosen===id}" data-topic-filter="${id}">${label}</button>`).join('')}</nav></section>${all?`<div class="journal-opening"><a class="journal-lead" href="#lezen/winnaar"><div class="journal-lead-art">${spreadArt('spotlight')}</div><div class="journal-lead-copy"><span class="small-label">Beleggingsverhaal</span><h2>De verleiding<br>van één winnaar.</h2><p>Een sterk verhaal. Maar hoeveel wilt u ervan laten afhangen?</p><span class="text-action">Lees het verhaal ${arrow}</span></div></a><a class="journal-try" href="#proberen/spreiding"><span class="small-label">Zelf proberen</span><h2>Wat als één<br>positie tegenvalt?</h2><div class="try-motif" aria-hidden="true"><span></span><i></i></div><span class="entry-action">Verken spreiding ${arrow}</span></a></div><div class="journal-grid" role="region" aria-label="Meer om te ontdekken" tabindex="0">${['fonds','asml','ritme'].map(journalCard).join('')}</div>`:`<div class="journal-grid filtered-journal">${Object.keys(journalEntries).filter(id=>journalEntries[id].type===chosen).map(journalCard).join('')}</div>`}`;}
function journalStory(id){const x=journalEntries[id],origin=history.state?.readingFrom||'#ontdekken',fromPlan=/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(origin),fromTrial=origin.startsWith('#proberen'),dest=x.concept==='inleg'?'#simuleren/ritme':'#proberen/spreiding';return `<div class="subpage-top">${back(fromPlan?'Terug naar uw plan':fromTrial?'Terug naar de verkenning':'Inzichten',origin)}</div><div class="reading-layout journal-reading"><article class="reading-paper"><span class="small-label">${x.kind}</span><h1>${x.title}</h1><p class="lead">${x.lead}</p>${id==='fonds'?fundArt():id==='winnaar'?`<div class="article-motif">${spreadArt()}</div>`:''}<div class="article-body">${x.body}${x.source?`<p class="article-source">Bron: <a href="${x.source}" target="_blank" rel="noreferrer">${id==='asml'?'ASML':'Wikifin'}</a></p>`:''}</div></article><aside class="reading-aside">${fromPlan?`<h2>Bij hetzelfde plan.</h2>${link('Terug naar uw plan',origin,'button return-context')}`:`<h2>${x.concept==='inleg'?'Wat doet<br>uw eigen inleg?':'En in<br>uw eigen geheel?'}</h2>${link(x.concept==='inleg'?'Verken uw inleg':'Probeer spreiding',dest,'button')}${link('Maak uw plan',`#voorbereiden/1/${id}`)}`}</aside></div>`;}
function conceptData(){const x=state.conceptTrial||{};return {weight:Number.isFinite(x.weight)?Math.max(0,Math.min(100,x.weight)):25,shock:40,source:x.source||null};}
function conceptLabel(x){return `Spreiding · één positie ${x.weight}% · voorbeeldscenario −${x.shock}%`;}
function conceptTest(){const x=conceptData(),origin=history.state?.simFrom||'#ontdekken',planOrigin=history.state?.simPlanOrigin;return `<div class="subpage-top">${back(/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(origin)?'Terug naar uw plan':origin.startsWith('#lezen')?'Terug naar het verhaal':'Inzichten',origin)}</div><section class="concept-test"><div class="concept-question"><span class="small-label">Spreiding · Verkenning</span><h1>Hoe zwaar weegt<br>één tegenvaller?</h1><p>Stel dat één positie <strong>40% daalt</strong> en de rest gelijk blijft.</p><p class="scenario-note">Vereenvoudigd voorbeeld. Geen koersverwachting of beoordeling van uw risico. Beleggingen kunnen ook samen dalen.</p></div><div class="concept-controls"><div class="weight-control"><label for="position-weight">Gewicht van die ene positie</label><div><output id="weight-value" for="position-weight">${x.weight}%</output><span>van het geheel</span></div><input id="position-weight" type="range" min="0" max="100" step="5" value="${x.weight}" style="--weight:${x.weight}%" aria-valuetext="${x.weight}% van de voorbeeldportefeuille"></div><div class="concept-effect" aria-live="polite" aria-atomic="true"><span>Verandering van het geheel</span><output id="portfolio-effect" for="position-weight">${x.weight?'−':''}${formatPct(x.weight*.4)}%</output><p id="effect-caption">Bij ${x.weight}% gewicht en een daling van 40%.</p></div><button class="button dark ${planOrigin?'return-context':''}" data-action="take-concept" data-plan-origin="${esc(planOrigin||'')}">${planOrigin?'Verder met uw plan':'Neem dit mee naar uw plan'} ${arrow}</button><a class="text-action" href="#lezen/spreiding">Lees de uitleg ${arrow}</a></div></section>`;}
const formatPct=n=>new Intl.NumberFormat('nl-BE',{maximumFractionDigits:1}).format(n);
function updateConcept(){const input=document.querySelector('#position-weight'),weight=Number(input.value),old=conceptData();state.conceptTrial={...old,weight};persist();input.setAttribute('aria-valuetext',weight+'% van de voorbeeldportefeuille');input.style.setProperty('--weight',weight+'%');document.querySelector('#weight-value').textContent=weight+'%';document.querySelector('#portfolio-effect').textContent=(weight?'−':'')+formatPct(weight*.4)+'%';document.querySelector('#effect-caption').textContent='Bij '+weight+'% gewicht en een daling van 40%.';}
function preparationSummary(snapshot=null){const concept=snapshot?snapshot.concept:state.preparationConcept,monthly=snapshot?snapshot.monthly:state.preparationSimulation,goal=snapshot?snapshot.goal:state.goal,source=snapshot?(snapshot.source||concept?.source):(state.preparationSource||concept?.source);return `<div class="conversation-context"><span class="small-label">Bij uw plan</span><h2>${esc(goal||'Wat u mogelijk wilt maken')}</h2>${concept?`<p>${esc(conceptLabel(concept))}</p>`:monthly?`<p>Uw verkenning: ${euros(monthly.monthly)} per maand, ${monthly.years} jaar</p>`:''}${source&&journalEntries[source]?`<p class="context-origin">Begonnen bij: ${journalEntries[source].title}</p>`:''}</div>`;}
function appointment(){return `<div class="subpage-top">${back('Terug naar uw voorbereiding','#voorbereiding-klaar')}<span class="breadcrumb">Ontwerpvoorbeeld</span></div><section class="appointment-layout"><div><h1>Hetzelfde plan.<br>Een mens erbij.</h1>${preparationSummary()}<p class="appointment-explanation">Uw voorbereiding en vragen vormen het vertrekpunt voor het gesprek.</p></div><form id="appointment-form" class="appointment-form"><fieldset><legend>Hoe spreekt u het liefst af?</legend><div class="appointment-modes">${[['video','Videogesprek'],['kantoor','Op kantoor']].map(([v,l])=>`<label><input type="radio" name="meeting-mode" value="${v}" ${state.appointmentMode===v||(!state.appointmentMode&&v==='video')?'checked':''}>${l}</label>`).join('')}</div></fieldset><fieldset><legend>Een moment om samen te kijken</legend><div class="appointment-slots">${['Dinsdag · 10:00','Woensdag · 16:00','Vrijdag · 11:30'].map((l,i)=>`<label><input type="radio" name="meeting-slot" value="${i}" required ${String(state.appointmentSlot)===String(i)?'checked':''}><span>${l}</span></label>`).join('')}</div></fieldset><details class="appointment-question"><summary>Een vraag meegeven</summary><label for="meeting-question">Uw vraag bij dit plan</label><textarea id="meeting-question" maxlength="500" placeholder="Waar wilt u samen naar kijken?">${esc(state.appointmentQuestion||'')}</textarea></details><p class="prototype-note">Fictieve momenten. In dit ontwerp wordt niets geboekt of verstuurd.</p><button class="button" type="submit">Vraag dit moment aan ${arrow}</button></form></section>`;}
function appointmentReady(){const x=state.requestDemo;if(!x)return appointment();return `<div class="subpage-top">${back('Terug naar de aanvraag','#afspraak')}<span class="breadcrumb">Fictieve vervolgstaat</span></div><section class="handoff-preview"><span class="small-label">Voorbeeld van de aanvraag</span><h1>Alles voor<br>hetzelfde gesprek.</h1><div class="handoff-details"><p>${['Dinsdag · 10:00','Woensdag · 16:00','Vrijdag · 11:30'][x.slot]} · ${x.mode==='video'?'Videogesprek':'Op kantoor'}</p>${preparationSummary(x)}${x.question?`<blockquote>${esc(x.question)}</blockquote>`:''}</div><p>Uw adviseur bespreekt de mogelijkheden met u. Een verkenning wordt pas een bevestigd plan na het adviesgesprek.</p><button class="button dark" data-action="preview-confirmed">Bekijk voorbeeld na het adviesgesprek ${arrow}</button><p class="prototype-note">Er is geen echte afspraakaanvraag verzonden.</p></section>`;}
function confirmedPlan(){const x=state.confirmedDemoSnapshot||(state.demoConfirmed?state.requestDemo:null)||{goal:state.goal,concept:state.preparationConcept,monthly:state.preparationSimulation,source:state.preparationSource};const source=x.source||x.concept?.source;return `<div class="subpage-top">${back('Mijn plan','#mijn-plan')}<span class="breadcrumb">Fictieve vervolgstaat</span></div><section class="confirmed-heading"><span class="small-label">Voorbeeld · Bevestigd door uw adviseur</span><h1>Uw plan.<br>Samen helder.</h1></section><div class="confirmed-document"><section><span class="small-label">Wat voor u telt</span><h2>${esc(x.goal||'Ruimte voor uw eigen plannen.')}</h2><p>Uw doelen, de ruimte die u wilt behouden en de besproken aanpak horen bij hetzelfde geheel.</p></section><section><span class="small-label">De besproken aanpak</span><h2>Uw doelen als vertrekpunt.</h2><p>Wat dichtbij is en wat later komt, bekijkt u in samenhang. De invulling en opvolging bespreekt u met uw adviseur.</p>${x.concept||source?`<div class="discussed-origin"><strong>Besproken: ${x.concept?'spreiding':esc(topics[source]?.name||'uw verkenning')}</strong>${source&&journalEntries[source]?`<span>Begonnen bij: ${journalEntries[source].title}</span>`:''}</div>`:''}<p class="confirmed-limit">Illustratieve planinhoud. Geen werkelijk advies of echte bevestiging.</p></section></div><section class="continuity-reading"><div><span class="small-label">Verder begrijpen bij uw plan</span><h2>Een nieuw inzicht.<br>Hetzelfde geheel.</h2></div>${link(source&&journalEntries[source]?'Lees het beginpunt opnieuw':'Lees over spreiding','#lezen/'+(source&&journalEntries[source]?source:'spreiding'))}</section>`;}

function home(){
 return `<section class="client-start" aria-labelledby="start-title">
<div class="task">
<h1 id="start-title">Wat wilt u met uw geld doen?</h1>
<div class="goals">
<a href="/ontwerp/klantreis-preview-09-11/?leeg=1&doel=groei"><span>Vermogen laten groeien</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></a>
<a href="/ontwerp/klantreis-preview-09-11/?leeg=1&doel=inkomen"><span>Uw inkomen aanvullen<small class="nkl-bijv">Bijvoorbeeld bij uw pensioen</small></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></a>
<a href="/ontwerp/klantreis-preview-09-11/?leeg=1&doel=iemand"><span>Sparen voor iemand anders</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></a>
<a href="/ontwerp/klantreis-preview-09-11/?leeg=1&doel=ander"><span>Een ander doel</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></a>
</div>
<a class="fiscal" href="/ontwerp/klantreis-preview-09-11/?leeg=1&doel=fiscaal">Fiscaal sparen verkennen <span aria-hidden="true">→</span></a>
</div>
<aside class="knowledge" aria-labelledby="knowledge-title">
<a href="/kennis/?v=kennis-20261106-v2#/" class="knowledge-link"><figure><img src="../assets/klantenstart/strand-gezin.jpg" width="1344" height="896" alt="Een moeder en twee kinderen wandelen langs de zee."></figure><div class="knowledge-text"><h2 id="knowledge-title">Sparen en beleggen begrijpen</h2><span class="read">Ontdek de artikels <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></span></div></a>
</aside>
</section>`;
}

function insightRow(id){const t=topics[id];return `<a class="insight-row" href="#lezen/${id}"><span class="small-label">${t.category}</span><h3>${t.title}</h3>${arrow}</a>`;}

const lessons=[
{id:'kind',category:'Familie & later',title:'Een goede start. Op hun eigen moment.',type:'Inzicht',time:'4 min'},
{id:'buffer',category:'Overzicht & reserve',title:'Wat wilt u achter de hand houden?',type:'Uitleg',time:'3 min'},
{id:'tijd',category:'Werk & vrijheid',title:'Wat als later wat eerder begint?',type:'Inzicht',time:'4 min'},
{id:'kind',category:'Familie & later',title:'Helpen, en zelf ruimte houden.',type:'Verdieping',time:'5 min'},
{id:'buffer',category:'Overzicht & reserve',title:'Wat heeft al een bestemming?',type:'Verdieping',time:'4 min'}];
function story(id){return journalEntries[id]?journalStory(id):legacyStory(id);}
function legacyStory(id){const t=topics[id]||topics.kind,deep=location.hash.endsWith('/verdieping'),title=deep?(id==='kind'?'Helpen, en zelf ruimte houden.':'Wat heeft al een bestemming?'):t.title,origin=history.state?.readingFrom||'#ontdekken',fromPlan=/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(origin),returnLabel=fromPlan?'Terug naar uw plan':origin==='#start'?'Startpagina':'Inzichten';return `<div class="subpage-top">${back(returnLabel,origin)}</div><div class="reading-layout"><article class="reading-paper"><span class="small-label">${deep?'Verdieping':'Inzicht'} · ${deep?'5':'4'} minuten</span><h1>${title}</h1><p class="lead">${t.lead}</p><div class="article-body"><h2>Begin bij wat voor u telt.</h2><p>${t.body}</p><div class="example-box"><p>${id==='buffer'?'Wat al een bestemming heeft, is iets anders dan wat u achter de hand houdt. Dat onderscheid helpt om ruimte te zien zonder hetzelfde geld twee keer te tellen.':id==='tijd'?'Meer tijd kan veel vormen aannemen. Een ander werkritme, een sabbatperiode of een vroeger pensioen. Eerst de wens begrijpen, daarna de financiële mogelijkheden verkennen.':'Misschien ligt het moment vast. Misschien wilt u vooral mogelijkheden openhouden. Dat verschil geeft het gesprek een goed vertrekpunt.'}</p></div><h2>Geef het een plaats in het geheel.</h2><p>Uw wensen staan niet los van elkaar. Wat u voor later mogelijk wilt maken, heeft ook te maken met de ruimte die u vandaag wilt behouden.</p><p>U hoeft nog geen antwoord klaar te hebben. Een vraag scherper zien is ook een stap vooruit.</p></div></article><aside class="reading-aside">${fromPlan?`<h2>Bij uw eigen plan.</h2>${link('Terug naar uw plan',origin,'button return-context')}`:`<h2>Wat kunt u<br>opzijzetten?</h2>${link('Probeer de simulatie',`#simuleren/${id}`,'button')}${link('Maak uw plan',`#voorbereiden/1/${id}`)}`}</aside></div>`;}

function begin(){const fromSim=history.state?.fromSimulation&&state.simulation,source=history.state?.beginFrom||'#start';return `<div class="subpage-top">${back(fromSim?'Terug naar uw simulatie':topic()?'Terug naar uw inzicht':'Startpagina',fromSim?source:topic()?`#lezen/${state.topic}`:'#start')}</div><section class="plan-begin focus-begin"><div><h1>Maak ruimte<br>voor uw plannen.</h1>${fromSim?`<div class="carried-exploration"><span>Uw verkenning</span><p>${euros(state.simulation.monthly)} per maand, ${state.simulation.years} jaar${topic()?` · ${esc(topic().name)}`:''}</p><small>Nog geen vastgelegde keuze.</small></div>`:topic()?`<p class="chosen-interest">${esc(topic().name)}</p>`:''}<div class="actions">${link('Begin uw plan','#voorbereiden/1','button')}</div><p class="notice">U bereidt zelf voor tot en met strategie. Concrete oplossingen bespreekt u met uw adviseur.</p></div>${process()}</section>`;}

function access(){return `<div class="subpage-top">${back('Startpagina','#start')}</div><section class="access-panel focus-access"><h1>Uw plan.<br>Op uw moment.</h1><div class="access-options"><a class="access-option" href="#eigen-plan"><h2>Mijn voorbereiding</h2>${arrow}</a><a class="access-option" href="${state.demoConfirmed?'#bevestigd-plan':'#adviseur-plan'}"><h2>Mijn adviseurplan</h2>${arrow}</a></div></section>`;}

function plan(advisor){const resume=Math.min(4,Math.max(1,Number(state.step)||3));return `<div class="subpage-top">${back('Mijn plan','#mijn-plan')}<span class="breadcrumb">Fictief planvoorbeeld</span></div><section class="plan-heading"><div><span class="small-label">${advisor?'Adviseurplan · Alleen bekijken':'Eigen voorbereiding'}</span><h1>${advisor?'Uw plan, bij elkaar.':'Uw plannen krijgen vorm.'}</h1></div></section>${!advisor?`<section class="own-resume"><p><strong>Verder bij 0${resume} · ${steps[resume-1][0]}</strong>Uw voorbereiding is nog niet afgerond.</p>${link('Verder voorbereiden',`#voorbereiden/${resume}`,'button')}</section>`:''}<div class="plan-document"><nav class="plan-index" aria-label="Onderdelen van uw plan"><div class="plan-tabs" role="tablist" aria-orientation="vertical">${[['doelen','Uw doelen'],['aanpak','De aanpak'],['afspraken','Afspraken']].map(([id,label])=>`<button role="tab" tabindex="${state.tab===id?0:-1}" id="tab-${id}" aria-controls="tab-content" aria-selected="${state.tab===id}" data-plan-tab="${id}">${label}</button>`).join('')}</div></nav><section id="tab-content" class="plan-tabcontent" role="tabpanel" tabindex="0" aria-labelledby="tab-${state.tab}">${tabContent(advisor)}</section></div><section class="plan-related"><h2>Bij dit onderdeel</h2><div>${relatedToTab()}</div></section>`;}
function goalOpen(key,fallback){return (state.expanded?.[key]??fallback)?"open":"";}
function relatedToTab(){return insightRow(state.tab==='aanpak'?'buffer':state.tab==='afspraken'?'tijd':'kind');}
function tabContent(advisor){const help=`<button class="text-action" data-action="plan-help">Een vraag bij dit onderdeel ${arrow}</button>`;if(state.tab==='aanpak')return `<div class="plan-tab-head"><h2>De besproken aanpak</h2>${help}</div><p class="plan-paragraph">Wat dichtbij is vraagt iets anders dan wat later komt. De aanpak vertrekt bij de samenhang tussen uw doelen en de ruimte die u wilt behouden.</p><div class="approach-grid"><section class="approach-item"><h3>Ruimte behouden</h3><p>Een reserve blijft afzonderlijk herkenbaar. Zo krijgt hetzelfde geld niet ongemerkt twee bestemmingen.</p></section><section class="approach-item"><h3>Uw doelen afwegen</h3><p>Moment, haalbaarheid en hoe u risico ervaart horen bij hetzelfde gesprek.</p></section></div><p class="plan-note">Fictieve samenvatting van een aanpak, zonder productkeuze of berekende uitkomst.</p>`;if(state.tab==='afspraken')return `<div class="plan-tab-head"><h2>Samen verder</h2>${help}</div><div class="appointment-row"><div><h3>Verandert er iets in uw leven?</h3><p>Een andere wens of situatie is een reden om het geheel opnieuw te bekijken.</p></div><span>Bij een verandering</span></div><div class="appointment-row"><div><h3>Vragen bij uw plan</h3><p>Bereid uw vraag voor bij het onderdeel waar ze over gaat. Zo blijft de context behouden.</p></div></div><p class="plan-note">Fictieve voorbeeldafspraken. Er is geen afspraak geboekt.</p>`;return `<div class="plan-tab-head"><h2>Wat u mogelijk wilt maken</h2>${help}</div>${!advisor&&state.goal?`<details class="goal-row" data-openkey="own-note" ${goalOpen("own-note",true)}><summary><div><h3>${esc(state.goal)}</h3><p>Uw eigen ontwerpnotitie</p></div><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="goal-detail"><p>Deze notitie blijft bij uw voorbereiding. Het is nog geen bevestigd doel of advies.</p>${link('Verder met uw doelen','#voorbereiden/3')}</div></details>`:`<details class="goal-row" data-openkey="${advisor?"advisor":"own"}-kind" ${goalOpen((advisor?"advisor":"own")+"-kind",true)}><summary><div><h3>Een kind op weg helpen</h3><p>Ruimte voor een eigen start.</p></div><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="goal-detail"><p>U wilt kunnen helpen wanneer het moment daar is, met aandacht voor de ruimte die u zelf nodig heeft.</p><dl><div><dt>Wat telt</dt><dd>Mogelijkheden openhouden</dd></div><div><dt>Wanneer</dt><dd>Samen te bepalen</dd></div></dl></div></details><details class="goal-row" data-openkey="${advisor?"advisor":"own"}-later" ${goalOpen((advisor?"advisor":"own")+"-later",false)}><summary><div><h3>Ruimte voor later</h3><p>Vrijheid om uw eigen ritme te kiezen.</p></div><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="goal-detail"><p>Meer tijd voor wat u belangrijk vindt. De wens wordt samen bekeken naast uw andere plannen.</p><dl><div><dt>Wat telt</dt><dd>Keuzevrijheid</dd></div><div><dt>Wanneer</dt><dd>Nog te bespreken</dd></div></dl></div></details>`}<p class="plan-note">${advisor?'Fictieve voorbeelddoelen. Dit raadpleegvoorbeeld is geen persoonlijk advies.':'Deze voorbeeldinvulling is geen afgeronde voorbereiding.'}</p>`;}
function prepare(n){state.step=n;persist();const s=steps[n-1]||steps[0];return `<div class="subpage-top">${back('Naar uw voorbereiding','#eigen-plan')}<span class="breadcrumb">Routevoorbeeld · 0${n} van 04</span></div><div class="journey-stage"><nav class="stage-nav" aria-label="Planonderwerpen">${steps.map((x,i)=>`<a href="#voorbereiden/${i+1}" ${i+1===n?'aria-current="step"':''}><span class="number">0${i+1}</span><span>${x[0]}</span></a>`).join('')}</nav><section class="stage-work"><span class="small-label">${s[0]}</span><h1>${s[1]}</h1>${context()}<p>${s[2]}</p>${n===3?`<div class="design-field"><label for="goal-note">Uw wens, in uw eigen woorden</label><input id="goal-note" name="goal-note" maxlength="160" placeholder="Bijvoorbeeld: een kind op weg helpen" value="${esc(state.goal)}"></div>`:''}<div class="actions"><button class="text-action" data-action="lizze">Eerst iets begrijpen ${arrow}</button>${link(n===4?'Bekijk het einde van de voorbereiding':'Volgend onderwerp',n===4?'#voorbereiding-klaar':`#voorbereiden/${n+1}`,'button dark')}</div><p class="prototype-note">Routeschets van de bestaande vier planonderwerpen. Er is nog geen dossier opgeslagen.</p></section></div>`;}
function boundary(){return `<div class="subpage-top">${back('Terug naar strategie','#voorbereiden/4')}</div><section class="preparation-bridge"><span class="small-label">Na onderwerp 04 · Ontwerpschets</span><h1>Uw plan begint<br>een gesprek.</h1>${preparationSummary()}<p>Uw verkenning is een vertrekpunt. Uw adviseur bespreekt de keuzes met u.</p><div class="actions">${link('Bespreek uw plan','#afspraak','button dark')}${link('Verder voorbereiden','#eigen-plan')}</div></section>`;}
function simulationConversation(){let c=null;try{c=JSON.parse(sessionStorage.getItem('norte-simulatie-gesprek-v1'))}catch{}const goals=['groei','inkomen','iemand','ander','ps','lts','vapz','poz','ipt'];if(c?.schema!=='norte-simulatie-gesprek/1'||!goals.includes(c.goal))return `<section class="sim-conversation"><h1>Uw gesprek voorbereiden</h1><p>Open uw doel eerst in de simulatie.</p><a class="text-action" href="/simulatie/">Terug naar uw simulatie ${arrow}</a></section>`;const back='/simulatie/#'+(['ps','lts','vapz','poz','ipt'].includes(c.goal)?'fiscalresult':'result')+'/'+c.goal;return `<section class="sim-conversation"><a class="back" href="${back}">${backArrow}Terug naar uw simulatie</a><div class="sim-conversation-grid"><div><h1>Een gesprek over uw doel.</h1><h2>${esc(c.title)}</h2><dl><div><dt>Moment</dt><dd>${esc(c.moment)}</dd></div><div><dt>Uw verkenning</dt><dd>${esc(c.input)}</dd></div><div><dt>Verkend profiel</dt><dd>${esc(c.profile)} · geen vastgesteld oordeel</dd></div></dl><p class="sim-conversation-limit">Deze simulatie geeft een vertrekpunt voor een gesprek. Een passende oplossing vraagt nog beoordeling.</p></div><div class="sim-note"><h2>Wat wilt u bespreken?</h2><form id="question-form"><label for="question">Een notitie voor uzelf</label><textarea id="question" name="question" maxlength="1000">${esc((state.questions||{})[draftKey()]||'')}</textarea><button class="button" type="submit">Bewaar uw notitie ${arrow}</button></form><div id="draft-result" role="status"></div><p>Alleen in deze browsersessie. Er wordt niets naar een adviseur verzonden.</p></div></div></section>`;}

function together(){if(location.hash==='#samen/simulatie')return simulationConversation();const hasPlan=location.hash.includes('/plan');return `<div class="subpage-top">${back(hasPlan?'Terug naar uw plan':'Terug naar uw startpagina',hasPlan?'#adviseur-plan':'#start')}<span class="breadcrumb">Samen verder</span></div><section class="contact-layout"><div><h1>Hetzelfde plan.<br>Een mens erbij.</h1><p>U hoeft uw verhaal niet opnieuw te beginnen. Uw vraag en de context van uw plan geven het gesprek een vertrekpunt.</p>${hasPlan?`<p class="context-tag">Bij uw adviseurplan · ${{doelen:'Uw doelen',aanpak:'De aanpak',afspraken:'Afspraken'}[state.tab]||'Uw doelen'}</p>`:context()}<button class="text-action" data-action="lizze">Eerst een vraag aan Lizze ${arrow}</button></div><div class="contact-panel"><span class="small-label">Een gesprek voorbereiden</span><h2>${hasPlan?'Wat wilt u bespreken?':'Waar wilt u samen naar kijken?'}</h2><p>Maak een notitie voor uzelf. U beslist later of en met wie u deze deelt.</p><form id="question-form"><div class="form-row"><label for="question">Uw vraag</label><textarea id="question" name="question" maxlength="1000" placeholder="Een vraag of verandering die u wilt bespreken">${esc((state.questions||{})[draftKey()]||'')}</textarea></div><button class="button" type="submit">Bewaar deze ontwerpnotitie ${arrow}</button></form><div id="draft-result" role="status"></div><p class="prototype-note">De notitie blijft alleen in deze browsersessie van het ontwerp. Er wordt niets naar een adviseur verzonden.</p></div></section>`;}
function draftKey(){if(location.hash==='#samen/simulatie'){try{const c=JSON.parse(sessionStorage.getItem('norte-simulatie-gesprek-v1'));return 'simulatie-'+(c?.goal||'doel')}catch{return 'simulatie-doel'}}return location.hash.includes('/plan')?'adviseur-'+state.tab:'voorbereiden-'+(state.topic||'algemeen');}

const euros=n=>new Intl.NumberFormat('nl-BE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
function simulationData(){const x=state.simulation||{};return {monthly:Number.isFinite(Number(x.monthly))?Math.max(0,Math.min(1000000,Number(x.monthly))):200,years:[1,5,10,15,20,25,30,40,50].includes(Number(x.years))?Number(x.years):10};}
function simulate(id){const t=topics[id],data=simulationData(),origin=history.state?.simFrom||'#start',fromPlan=history.state?.simPlanOrigin;return `<div class="subpage-top">${back(origin.startsWith('#lezen')?'Terug naar het inzicht':/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(origin)?'Terug naar uw plan':origin.startsWith('#ontdekken')?'Inzichten':'Startpagina',origin)}</div><section class="quick-simulation"><div class="simulation-intro"><h1>Wat als u elke maand<br>iets opzijzet?</h1>${t?`<p class="chosen-interest">${esc(t.name)}</p>`:''}</div><form id="simulation-form" data-topic="${t?id:''}" data-plan-origin="${esc(fromPlan||'')}"><div class="simulation-fields"><div class="amount-control"><label for="sim-monthly">Per maand</label><div class="amount-input"><span aria-hidden="true">€</span><input id="sim-monthly" name="monthly" type="number" inputmode="numeric" min="0" max="1000000" step="1" required value="${data.monthly}"></div><input id="sim-range" type="range" min="0" max="${Math.max(1000,Math.ceil(data.monthly/1000)*1000)}" step="1" value="${data.monthly}" aria-label="Maandelijks bedrag aanpassen"></div><div class="years-control"><label for="sim-years">Hoelang?</label><select id="sim-years" name="years">${[1,5,10,15,20,25,30,40,50].map(n=>`<option value="${n}" ${n===data.years?'selected':''}>${n} jaar</option>`).join('')}</select></div></div><div class="simulation-result" aria-live="polite" aria-atomic="true"><output id="sim-total" for="sim-monthly sim-years">${euros(data.monthly*12*data.years)}</output><p id="sim-caption">aan inleg over ${data.years} jaar</p></div><p class="calculation-note">Alleen uw inleg. Zonder rendement of inflatie.</p><button type="submit" class="button dark ${fromPlan?'return-context':''}">${fromPlan?'Verder met uw plan':'Maak hier uw plan van'} ${arrow}</button></form></section>`;}
function updateSimulation(){const amount=document.querySelector('#sim-monthly'),years=document.querySelector('#sim-years'),range=document.querySelector('#sim-range'),valid=amount.validity.valid&&amount.value!=='';if(valid){const monthly=Number(amount.value),y=Number(years.value);state.simulation={monthly,years:y};persist();range.max=String(Math.max(1000,Math.ceil(monthly/1000)*1000));range.value=String(monthly);document.querySelector('#sim-total').textContent=euros(monthly*12*y);document.querySelector('#sim-caption').textContent='aan inleg over '+y+' jaar';}else{document.querySelector('#sim-total').textContent='—';document.querySelector('#sim-caption').textContent='Vul een heel bedrag tussen €0 en €1.000.000 in.';}}
document.addEventListener('input',e=>{if(e.target.id==='sim-range'){document.querySelector('#sim-monthly').value=e.target.value;updateSimulation();}else if(e.target.id==='sim-monthly')updateSimulation();});
document.addEventListener('change',e=>{if(e.target.id==='sim-years')updateSimulation();});
document.addEventListener('submit',e=>{if(e.target.id==='simulation-form'){e.preventDefault();updateSimulation();const form=e.target,planOrigin=form.dataset.planOrigin;if(planOrigin){if(planOrigin.startsWith('#voorbereiden')){state.preparationSimulation={...simulationData()};persist();}navigate(planOrigin,form.querySelector('button'));return;}state.simulation=simulationData();persist();navigate('#voorbereiden/1'+(form.dataset.topic?'/'+form.dataset.topic:''),form.querySelector('button'));}});
const pages={afspraak:appointment,'afspraak-klaar':appointmentReady,'bevestigd-plan':confirmedPlan,start:home,ontdekken:discover,beginnen:begin,'mijn-plan':access,'eigen-plan':()=>plan(false),'adviseur-plan':()=>plan(true),samen:together,'voorbereiding-klaar':boundary};
let currentKey='first',counter=0;const positions=new Map(),routePositions=new Map(),routeContexts=new Map();let renderedRoute=location.hash||'#start';history.replaceState({...history.state,key:currentKey},'',location.href);
const capture=(focusEl=document.activeElement)=>{const pos={scroll:scrollY,focus:focusEl?.dataset?.focus};positions.set(currentKey,pos);routePositions.set(renderedRoute,pos);};
function render(restore=false){const shared=centralNorteDestination(location.hash);if(shared){location.replace(shared);return;}renderedRoute=location.hash||'#start';routeContexts.set(renderedRoute,{...history.state});const parts=(location.hash.slice(1)||'start').split('/'),page=parts[0];if(page==='beginnen'){state.topic=topics[parts[1]]?parts[1]:null;persist();}const html=page==='proberen'?conceptTest():page==='simuleren'?simulate(parts[1]):page==='lezen'?story(parts[1]):page==='voorbereiden'?prepare(Math.min(4,Math.max(1,Number(parts[1])||1))):(pages[page]||home)();root.innerHTML=html;root.dataset.view=page;const homeActive=Boolean(root.querySelector('.client-start'));document.body.classList.toggle('client-home',homeActive);document.querySelectorAll('[data-home-credit]').forEach(el=>el.hidden=!homeActive);document.querySelector('.lizze-open span').textContent='Lizze';document.querySelectorAll('.site-footer [data-home-internal]').forEach(el=>el.hidden=homeActive||location.hash==='#samen/simulatie');root.querySelectorAll('a,button,input,textarea,summary,select').forEach((el,i)=>el.dataset.focus=String(i));document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(['lezen','ontdekken'].includes(page)?'ontdekken':['beginnen','voorbereiden','voorbereiding-klaar'].includes(page)?'beginnen':'');active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.querySelector('.my-plan').setAttribute('aria-current',['mijn-plan','eigen-plan','adviseur-plan','bevestigd-plan'].includes(page)?'page':'false');document.querySelector('.plan-tabs')?.setAttribute('aria-orientation',matchMedia('(max-width:760px)').matches?'horizontal':'vertical');document.title=(page==='ontdekken'?'Inzichten':page==='simuleren'?'Snelle simulatie':root.querySelector('h1')?.innerText.replace(/\s+/g,' ').trim()||'Norte')+' — Norte';if(!restore){root.focus({preventScroll:true});window.scrollTo(0,0);if(!reduced&&page==='beginnen'&&topic())root.querySelector('.context-tag')?.classList.add('context-enter');}else{const pos=positions.get(currentKey);requestAnimationFrame(()=>{if(pos){window.scrollTo(0,pos.scroll);if(pos.focus!==undefined)root.querySelector(`[data-focus="${pos.focus}"]`)?.focus({preventScroll:true});}else{root.focus({preventScroll:true});window.scrollTo(0,0);}});}if(page==='start'&&!reduced){let shown=false;try{shown=sessionStorage.getItem('norte-koers-arrival')==='1';sessionStorage.setItem('norte-koers-arrival','1');}catch{}if(!shown)root.classList.add('arrival');else root.classList.remove('arrival');}else root.classList.remove('arrival');}
function navigate(hash,trigger){const shared=centralNorteDestination(hash);if(shared){capture(trigger);location.assign(shared);return;}capture(trigger);const from=location.hash||'#start',previous=history.state||{};if(hash.startsWith('#proberen')){if(!trigger?.dataset.conceptTrial&&!trigger?.classList.contains('back')){state.conceptTrial={...conceptData(),source:from.startsWith('#lezen/')?from.split('/')[1]:null};persist();}}let readingFrom,simFrom,simPlanOrigin,fromSimulation=false,beginFrom;if(hash.startsWith('#lezen/')){readingFrom=from.startsWith('#beginnen')?(state.lastReadingOrigin||'#ontdekken'):from;state.lastReadingOrigin=readingFrom;persist();}if(hash.startsWith('#simuleren')||hash.startsWith('#proberen')){simFrom=from;simPlanOrigin=/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(from)?from:/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(previous.readingFrom||'')?previous.readingFrom:undefined;}if(hash.startsWith('#beginnen')){fromSimulation=from.startsWith('#simuleren');beginFrom=from;if(!fromSimulation)state.preparationSimulation=null;persist();}if(hash.startsWith('#voorbereiden/1')&&!/^#(eigen-plan|adviseur-plan|voorbereiden|bevestigd-plan)/.test(from)){const routeTopic=hash.split('/')[2];if(!previous.simPlanOrigin){state.preparationSource=from.startsWith('#lezen/')?from.split('/')[1]:from.startsWith('#proberen')?conceptData().source:from.startsWith('#simuleren')&&previous.simFrom?.startsWith('#lezen/')?previous.simFrom.split('/')[1]:null;}if(from.startsWith('#proberen')){state.preparationConcept={...conceptData()};state.preparationSimulation=null;}else{state.preparationConcept=null;}if(from.startsWith('#simuleren')){state.preparationSimulation={...simulationData()};state.topic=topics[routeTopic]?routeTopic:null;}else if(from.startsWith('#beginnen')){state.preparationSimulation=previous.fromSimulation?{...simulationData()}:null;}else{state.preparationSimulation=null;state.topic=topics[routeTopic]?routeTopic:null;}persist();}if(dialog.open)dialog.close();const restore=(trigger?.classList.contains('back')||trigger?.classList.contains('return-context'))&&routePositions.has(hash),saved=routePositions.get(hash);history.pushState({...((restore&&routeContexts.has(hash))?routeContexts.get(hash):{readingFrom,simFrom,simPlanOrigin,fromSimulation,beginFrom}),key:'entry-'+(++counter)+'-'+Date.now()},'',hash);currentKey=history.state.key;if(restore)positions.set(currentKey,saved);render(restore);}
window.addEventListener('popstate',()=>{capture();currentKey=history.state?.key||'first';render(true);});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){if(a.getAttribute('href')==='#main'){e.preventDefault();root.focus();return;}e.preventDefault();if(a.dataset.simPreset){state.simulation={monthly:Number(a.dataset.simPreset),years:10};persist();}else if(a.dataset.conceptTrial&&state.preparationConcept){state.conceptTrial={...state.preparationConcept};persist();}else if(a.dataset.simTrial&&state.preparationSimulation){state.simulation={...state.preparationSimulation};persist();}navigate(a.getAttribute('href'),a);return;}const filter=e.target.closest('[data-topic-filter]');if(filter){navigate('#ontdekken/'+filter.dataset.topicFilter,filter);document.querySelector(`[data-topic-filter="${filter.dataset.topicFilter}"]`)?.focus({preventScroll:true});return;}const tab=e.target.closest('[data-plan-tab]');if(tab){state.tab=tab.dataset.planTab;persist();document.querySelectorAll('[data-plan-tab]').forEach(x=>{x.setAttribute('aria-selected',String(x===tab));x.tabIndex=x===tab?0:-1;});const pane=document.querySelector('#tab-content');pane.setAttribute('aria-labelledby',tab.id);pane.innerHTML=tabContent(location.hash.includes('adviseur'));document.querySelector('.plan-related>div').innerHTML=relatedToTab();root.querySelectorAll('a,button,input,textarea,summary,select').forEach((el,i)=>el.dataset.focus=String(i));return;}const action=e.target.closest('[data-action]');if(action)act(action.dataset.action,action);});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-plan-tab]');if(tab&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-plan-tab]')],i=tabs.indexOf(tab),n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click();}});
document.addEventListener('input',e=>{if(e.target.id==='goal-note'){state.goal=e.target.value;persist();}if(e.target.id==='question'){state.questions=state.questions||{};state.questions[draftKey()]=e.target.value;persist();}});
