let returnFocus,returnScroll=0;function show(label,title,body,trigger){returnFocus=trigger||document.activeElement;returnScroll=scrollY;document.querySelector('#help-label').textContent=label;document.querySelector('#help-title').textContent=title;document.querySelector('#help-body').innerHTML=body;if(!dialog.open)dialog.showModal();dialog.querySelector('[data-action="close-dialog"]').focus();}
dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else root.focus({preventScroll:true});window.scrollTo(0,returnScroll);});

function helpContext(){const parts=location.hash.slice(1).split('/'),page=parts[0];if(page==='bevestigd-plan')return 'Uw bevestigde plan · voorbeeld';if(['afspraak','afspraak-klaar'].includes(page))return 'Uw plan · gesprek met een adviseur';if(['adviseur-plan','eigen-plan'].includes(page))return (page==='adviseur-plan'?'Uw adviseurplan':'Uw voorbereiding')+' · '+({doelen:'Uw doelen',aanpak:'De aanpak',afspraken:'Afspraken'}[state.tab]||'Uw doelen');if(page==='samen'&&parts[1]==='plan')return 'Uw adviseurplan · '+({doelen:'Uw doelen',aanpak:'De aanpak',afspraken:'Afspraken'}[state.tab]||'Uw doelen');if(page==='proberen')return 'Spreiding verkennen';if(page==='simuleren')return 'Snelle simulatie'+(topics[parts[1]]?' · '+topics[parts[1]].name:'');if(page==='lezen'&&topics[parts[1]])return topics[parts[1]].name;if(page==='voorbereiden')return 'Uw voorbereiding · '+steps[Math.max(0,Math.min(3,Number(parts[1])-1))][0];return topic()&&page==='beginnen'?topic().name:'Uw mogelijkheden';}
function panelDraftKey(){return 'paneel-'+location.hash+'-'+(state.tab||'doelen');}
function act(action,trigger){if(action==='take-concept'){const planOrigin=trigger.dataset.planOrigin;if(planOrigin){if(planOrigin.startsWith('#voorbereiden')){state.preparationConcept={...conceptData()};state.preparationSimulation=null;persist();}navigate(planOrigin,trigger);}else navigate('#voorbereiden/1/spreiding',trigger);return;}if(action==='preview-confirmed'){state.demoConfirmed=true;if(state.requestDemo)state.confirmedDemoSnapshot=JSON.parse(JSON.stringify(state.requestDemo));persist();navigate('#bevestigd-plan',trigger);return;}if(action==='close-dialog'){dialog.close();return;}if(action==='about'){show('Koers · Klikbaar ontwerp','Een geheel om op terug te komen.','<p>Ontdekken, zelfstandig voorbereiden en een plan raadplegen binnen dezelfde omgeving. Het ontwerp onderzoekt die samenhang; teksten en planinhoud zijn voorlopige voorbeelden.</p><p>Geen echte login, AI-assistent, dossieropslag of externe verzending. De inlegsimulatie telt maandelijkse bijdragen op. De spreidingsverkenning toont een hypothetische verandering van één positie terwijl de rest gelijk blijft. Afspraak en adviseurbevestiging zijn fictieve vervolgbeelden; er wordt niets geboekt of bevestigd. De vier planstappen zijn een routeschets. Planinhoud en teksten zijn fictieve voorbeelden. Notities blijven alleen in deze tabsessie.</p><a class="text-action" href="?motion=off#start">Bekijk zonder beweging</a>',trigger);return;}if(action==='lizze'&&document.body.classList.contains('client-home')){show('Lizze','Waar zoekt u uitleg over?',`<p><a href="/kennis/" class="button dark">Sparen en beleggen begrijpen ${arrow}</a></p>`,trigger);return;}if(action==='lizze'||action==='plan-help'){show('Lizze · Ontwerpvoorbeeld','Waar wilt u bij stilstaan?',`<p class="context-tag">Bij: ${esc(helpContext())}</p><div class="help-choices"><button data-action="explain">Iets beter begrijpen ${arrow}</button><button data-action="advisor-question">Een vraag voor uw adviseur ${arrow}</button></div><p class="prototype-note">Voorbeeldinteractie met vaste antwoorden. Geen actieve AI-verbinding.</p>`,trigger);return;}if(action==='explain'){document.querySelector('#help-title').textContent='Hetzelfde plan. Een nieuw perspectief.';document.querySelector('#help-body').innerHTML=`<p class="context-tag">Bij: ${esc(helpContext())}</p><p>Een inzicht kan helpen om uw wens scherper te zien. Het verandert uw plan niet. Uw keuzes bevestigt u in uw voorbereiding of bespreekt u met uw adviseur.</p><p>Zelf kunt u voorbereiden tot en met stap 04 Strategie. Concrete oplossingen bespreekt u vervolgens samen.</p><button class="button" data-action="close-dialog">Verder waar u was</button>`;dialog.querySelector('#help-body button').focus();return;}if(action==='advisor-question'){document.querySelector('#help-title').textContent='Wat wilt u bespreken?';document.querySelector('#help-body').innerHTML=`<p class="context-tag">Bij: ${esc(helpContext())}</p><form id="panel-question-form"><div class="form-row"><label for="panel-question">Uw vraag aan uw adviseur</label><textarea id="panel-question" maxlength="1000" placeholder="Een vraag of verandering die u wilt bespreken">${esc((state.questions||{})[panelDraftKey()]||'')}</textarea></div><button class="button" type="submit">Bewaar mijn ontwerpnotitie</button></form><div id="panel-draft-result" role="status"></div><p class="prototype-note">Alleen een notitie in deze tabsessie. Er wordt niets naar een adviseur verzonden.</p>`;dialog.querySelector('textarea').focus();return;}}
